cypress_script:
describe('User Avatars Profile Links', () => {
  it('should reveal profile link on hover', () => {
    cy.visit('https://the-internet.herokuapp.com/hovers');
    cy.get('.figure:nth-child(1)').trigger('mouseover');
    cy.contains('View profile').should('be.visible');
    cy.get('.figure:nth-child(2)').trigger('mouseover');
    cy.contains('View profile').should('be.visible');
    cy.get('.figure:nth-child(3)').trigger('mouseover');
    cy.contains('View profile').should('be.visible');
  });

  it('should not navigate away from the page on hover', () => {
    cy.visit('https://the-internet.herokuapp.com/hovers');
    cy.get('.figure:nth-child(1)').trigger('mouseover');
    cy.url().should('eq', 'https://the-internet.herokuapp.com/hovers');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('User Avatars Profile Links', () => {
  test('should reveal profile link on hover', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/hovers');
    await page.hover('.figure:nth-child(1)');
    await expect(page.locator('text=View profile')).toBeVisible();
    await page.hover('.figure:nth-child(2)');
    await expect(page.locator('text=View profile')).toBeVisible();
    await page.hover('.figure:nth-child(3)');
    await expect(page.locator('text=View profile')).toBeVisible();
  });

  test('should not navigate away from the page on hover', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/hovers');
    await page.hover('.figure:nth-child(1)');
    await expect(page.url()).toBe('https://the-internet.herokuapp.com/hovers');
  });
});
